"""Self-contained review viewer. Coordinate truth is source JSON, not physical markings."""
from pathlib import Path
import json,hashlib
p=Path(__file__).resolve().parent/'electrical-panel-candidate-v3';board=p/'panel.kicad_pcb';out=p/('fabrication-review-'+hashlib.sha256(board.read_bytes()).hexdigest()[:12]);src=out/'assembly-terminal-orientation.json';r=json.loads(src.read_text());assert r['source_pcb_sha256']==hashlib.sha256(board.read_bytes()).hexdigest()
layout=json.loads((p.parent/'supported-panel-topology-study.json').read_text());data=json.dumps({'components':r['components'],'units':layout['units']},ensure_ascii=False).replace('<','\\u003c')
html='''<!doctype html><meta charset="utf-8"><title>Assembly coordinate review</title><style>body{font:16px system-ui;margin:24px;color:#142638}header{position:sticky;top:0;background:white;padding:10px;z-index:1}select,input{font:inherit;margin:8px}main{display:grid;grid-template-columns:minmax(500px,1fr) minmax(400px,1fr);gap:24px}svg{width:100%;border:1px solid #ccd;max-height:85vh}table{border-collapse:collapse;width:100%}td,th{padding:6px;border-bottom:1px solid #ddd;text-align:left}tr:hover{background:#edf5ff}.note{color:#954000}button{font:inherit}#detail{white-space:pre-wrap}</style><header><h1>実装座標の確認 — 製造承認前</h1><label>基板<select id="unit"></select></label><label>面<select id="side"><option value="top">表</option><option value="bottom">裏</option></select></label><label>部品検索<input id="search" placeholder="U1 / C12"></label><p class="note">両面とも表から見た座標です。裏面は鏡像にしていません。赤点は設計上の端子1/A1で、実部品の極性・テープ方向の保証ではありません。</p></header><main><section><svg id="map" viewBox="-1 -1 26 29"></svg><p id="detail">部品をクリックすると端子一覧を表示します。</p></section><section><table><thead><tr><th>部品</th><th>値</th><th>角度</th><th>全体座標 X,Y mm</th></tr></thead><tbody id="rows"></tbody></table></section></main><script>const data=DATA;
const $=id=>document.getElementById(id),ns='http://www.w3.org/2000/svg';
for(const u of data.units){let o=document.createElement('option');o.value=u.unit;o.textContent=u.unit;$('unit').append(o)}
function svg(tag,attrs,text){let e=document.createElementNS(ns,tag);for(let [k,v] of Object.entries(attrs))e.setAttribute(k,v);if(text)e.textContent=text;return e}
function detail(c){$('detail').textContent=c.reference+' — '+c.value+'\n'+c.terminals.map(t=>t.number+': '+t.net+'  ('+t.x_mm+', '+t.y_board_mm+')').join('\n')}
function draw(){let n=Number($('unit').value),u=data.units.find(u=>u.unit===n),[x,y]=u.bounds_mm,map=$('map');map.replaceChildren(svg('rect',{x:0,y:0,width:24,height:27,fill:'#f7fbff',stroke:'#555','stroke-width':.08}));$('rows').replaceChildren();let search=$('search').value.trim().toUpperCase();for(let c of data.components.filter(c=>c.reference.startsWith('P'+n+'_')&&c.side===$('side').value)){let short=c.reference.split('_')[1],match=!search||short.includes(search),g=svg('g',{opacity:match?1:.15});for(let t of c.terminals)g.append(svg('circle',{cx:t.x_mm-x,cy:t.y_board_mm-y,r:.07,fill:'#8b98a6'}));let a=c.orientation_anchor;if(a)g.append(svg('circle',{cx:a.x_mm-x,cy:a.y_board_mm-y,r:.11,fill:'#c52b20'}));g.append(svg('text',{x:c.x_mm-x,y:c.y_board_mm-y,'font-size':.43,'text-anchor':'middle',fill:'#142638'},short));g.append(svg('title',{},c.reference+' '+c.value));g.style.cursor='pointer';g.onclick=()=>detail(c);map.append(g);if(match){let tr=document.createElement('tr');for(let v of [c.reference,c.value,c.kicad_orientation_degrees,[c.x_mm,c.y_board_mm].join(', ')]){let td=document.createElement('td');td.textContent=v;tr.append(td)}tr.onclick=()=>detail(c);$('rows').append(tr)}}}
for(let id of ['unit','side','search'])$(id).addEventListener('input',draw);draw();</script>'''.replace('DATA',data)
# JS newline escapes must remain escape sequences inside quoted JS strings.
html=html.replace("+'\n'+", "+'\\n'+").replace(".join('\n')", ".join('\\n')")
(out/'assembly-coordinate-view.html').write_text(html)
(out/'assembly-coordinate-view-review.json').write_text(json.dumps({'status':'GENERATED_OFFLINE_REVIEW_VIEWER','source_json_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'component_count':len(r['components']),'views':12,'limitations':['Interactive rendering not yet browser-tested.','Dense labels may overlap; search and table provide explicit lookup.','No component body models or physical polarity approval.']},indent=2)+'\n');print(out/'assembly-coordinate-view.html')
